def select(data: OrderData): Behavior[Command] = Behaviors.receiveMessage {
  case Choose(id) => amount(data.copy(account = id))
  case Flush      => Behaviors.stopped
}
def amount(data: OrderData): Behavior[Command] = Behaviors.receiveMessage {
  case Next if data.valid => confirm(data)     // the guard decides the transition
  case Next               => Behaviors.same    // rejected: stay in this step
}
object OrderFlow {
  val flow: Behavior[Command] = Behaviors.setup(_ => select(OrderData.empty))
}
